investors = {"A": 300_000, "B": 500_000, "C": 200_000}
repay = 33_334
total = sum(investors.values())
share = {k: repay * v // total for k, v in investors.items()}
left = repay - sum(share.values())
order = sorted(investors, key=lambda k: -(repay * investors[k] % total))
for k in order[:left]:
    share[k] += 1
print("배분:", share, "합계:", sum(share.values()), "== 상환금" if sum(share.values()) == repay else "!= 상환금")

def can_execute(requested, raised):
    if raised < requested:
        return f"모집 {raised:,}/{requested:,}원 — 실행 불가"
    return "모집 완료 — 실행 가능"
print(can_execute(10_000_000, 9_200_000))
print(can_execute(10_000_000, 10_000_000))

ledger = {"R1": 120_000, "R2": 80_000, "R3": 50_000}
bank = {"R1": 120_000, "R2": 75_000, "R4": 30_000}
for k in sorted(ledger.keys() | bank.keys()):
    a, b = ledger.get(k), bank.get(k)
    if a != b:
        print(k, "원장", a, "/ 예치기관", b, "→ 확인 필요")

done = {}
balance = {"loan-1": 1_000_000}
def pay(key, loan, amount):
    if key in done:
        return done[key] + " (중복 요청 — 처리 안 함)"
    balance[loan] -= amount
    done[key] = f"상환 {amount:,}원, 남은 원금 {balance[loan]:,}원"
    return done[key]
print(pay("req-7f3", "loan-1", 100_000))
